update clips set title = 'First-person Perspective', summary = 'First-person perspective, immersive ARPG dialogue scene, single continuous shot. A small white rabbit adventurer stands directly in front of the camera. Its fur is soft and finely detailed, and its right eye is a glowing red mechanical eye.', runtime_s = 3, aspect_ratio = null, shot_count = 5, realism_level = 'stylized-real', grade = null, motion_feel = '24fps-cinematic' where clip_id = 'APX-C-3608';
delete from shots where clip_id = 'APX-C-3608';
insert into shots (shot_id, clip_id, shot_index, tc_in, tc_out, duration_s,
  verbatim_text, description, subject_role, action, food_item, food_role, setting, mood) values
('APX-S-3608-1', 'APX-C-3608', 1, null, null, null, 'First-person perspective, immersive ARPG dialogue scene, single continuous shot. A small white rabbit adventurer stands directly in front of the camera. Its fur is soft and finely detailed, and its right eye is a glowing red mechanical eye. It reaches out toward the camera in an inviting gesture, with a calm and confident demeanor. The environment is a vast fantasy world: rolling green grasslands, ruined ancient stone structures, distant mountain ranges, and a lightly smoking volcano.', 'A small white rabbit adventurer stands directly in front of the camera. It reaches out toward the camera in an inviting gesture, with a calm and confident demeanor.', 'animal-character', null, null, null, 'mountain', 'calm'),
('APX-S-3608-2', 'APX-C-3608', 2, null, null, null, 'The morning light is soft, the air is clear, and a gentle breeze moves the grass and leaves, creating a strong cinematic atmosphere with depth. The camera is in first-person view, with slight handheld motion and natural breathing sway. Shallow depth of field, cinematic realism. The rabbit looks directly into the camera and says: “Good morning, adventurer. It’s time to set out.” A semi-transparent game UI (modern ARPG style) appears on the right side: Alright, let’s go.', 'The camera is, with slight motion and natural breathing sway. The rabbit looks directly into the camera and says: “Good morning, adventurer.', 'animal-character', null, null, null, null, 'calm'),
('APX-S-3608-3', 'APX-C-3608', 3, null, null, null, 'Not right now. Why not? The cursor moves smoothly twice, pauses for 0.3 seconds, then selects “Why not?” The rabbit smiles slightly, tilts its head, and responds in a relaxed tone: “Sure.” In the next moment, all UI elements (dialogue box, options, health bar, minimap) fade out smoothly, returning the scene to a clean, UI-free world. The rabbit turns around, its cloak and backpack swaying naturally with physics, and begins walking forward along a stone path.', 'The cursor moves smoothly twice, pauses for 0.3 seconds, then selects “Why not?” The rabbit smiles slightly, tilts its head, and responds in a relaxed tone: “Sure.” In the next moment, all UI elements (dialogue box, options, health bar…', 'animal-character', null, null, null, null, 'calm'),
('APX-S-3608-4', 'APX-C-3608', 4, null, null, null, 'The camera maintains a first-person follow, with subtle handheld motion, synchronized with the character’s walking rhythm. While walking, the rabbit raises its hand and points toward the distant horizon (mountains and a faint city silhouette), saying: “Look, that’s our destination.” A brief pause of about 0.5 seconds. The wind intensifies slightly, causing more noticeable movement in the grass and clothing, enhancing the epic atmosphere.', 'The camera maintains a first-person follow, with subtle motion, synchronized with the character’s walking rhythm.', 'animal-character', null, null, null, null, 'epic'),
('APX-S-3608-5', 'APX-C-3608', 5, null, null, null, 'The rabbit continues walking and says: “We have to get there before 8:08 PM.” The camera slowly pushes forward, focusing toward the distance. The far view transitions from slightly blurred to clear, with a subtle lens flare appearing, reinforcing the sense of a journey beginning and a clear objective. No subtitles, no background music. Only natural ambient sounds: wind, footsteps, and distant birds.', 'The rabbit continues walking and says: “We have to get there before PM.” The camera slowly pushes forward, focusing toward the distance.', 'animal-character', null, null, null, null, null)
on conflict (shot_id) do nothing;

