update clips set title = 'Night', summary = 'Night. Large abandoned Indian hospital corridor. Flickering fluorescent lights. Rusted wheelchairs, peeling paint, old hospital signs, long empty hallway stretching into darkness. Everything clearly visible.', runtime_s = null, aspect_ratio = null, shot_count = 4, realism_level = 'stylized-real', grade = null, motion_feel = '24fps-cinematic' where clip_id = 'APX-C-5532';
